// Patrón: lazy loading con caché manual
const cache = new Map();

async function importarUnaVez(ruta) {
  if (cache.has(ruta)) {
    return cache.get(ruta);
  }
  const modulo = await import(ruta);
  cache.set(ruta, modulo);
  return modulo;
}

// El navegador ya cachea automáticamente,
// pero este patrón es útil para simular módulos dinámicos
// o para entornos donde el caché no está garantizado
console.log('El caché de módulos nativo es automático en ESM');

// Simular lazy loading de componente pesado
async function cargarComponentePesado(nombre) {
  const componentes = {
    Editor: { render: () => '<Editor />', peso: '500KB' },
    Mapa: { render: () => '<Mapa />', peso: '800KB' },
    Grafico: { render: () => '<Grafico />', peso: '300KB' },
  };

  // Simula la carga asíncrona
  await new Promise(r => setTimeout(r, 100)); // delay simulado
  return componentes[nombre] ?? null;
}

async function mostrarComponente(nombre) {
  console.log(`Cargando ${nombre}...`);
  const componente = await cargarComponentePesado(nombre);
  if (componente) {
    console.log(`${nombre} cargado (${componente.peso}): ${componente.render()}`);
  } else {
    console.log(`Componente ${nombre} no encontrado`);
  }
}

await mostrarComponente('Editor');
await mostrarComponente('Mapa');

