const _modulos = {
  matematicas: { sumar: (a, b) => a + b, PI: 3.14 },
  strings: { mayusculas: s => s.toUpperCase() },
};

function importarSimulado(nombre) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (_modulos[nombre]) {
        resolve(_modulos[nombre]);
      } else {
        reject(new Error('Módulo no encontrado: ' + nombre));
      }
    }, 50);
  });
}

// Usa async/await para cargar 'matematicas'
const modulo = await importarSimulado('matematicas');
const r = modulo.sumar(10, 5);
const pi = modulo.PI;

console.log(r, pi); // 15, 3.14

const paginas = {
  inicio: () => Promise.resolve({ default: { titulo: 'Inicio', render: () => '<h1>Inicio</h1>' } }),
  productos: () => Promise.resolve({ default: { titulo: 'Productos', render: () => '<h1>Productos</h1>' } }),
  contacto: () => Promise.resolve({ default: { titulo: 'Contacto', render: () => '<h1>Contacto</h1>' } }),
};

async function navegar(ruta) {
  if (!paginas[ruta]) return null;
  const modulo = await paginas[ruta]();
  return modulo.default;
}

const paginaInicio = await navegar('inicio');
const paginaNull = await navegar('admin');
const html = paginaInicio.render();

console.log(paginaInicio.titulo, html, paginaNull);

const _validadores = {
  login: {
    validar: (d) => d.usuario?.length > 0 && d.password?.length >= 6,
  },
  registro: {
    validar: (d) => d.email?.includes('@') && d.password?.length >= 8,
  },
  pago: {
    validar: (d) => /^\d{16}$/.test(d.tarjeta),
  },
};

function cargarValidador(contexto) {
  return new Promise((resolve, reject) => {
    if (_validadores[contexto]) {
      resolve({ default: _validadores[contexto] });
    } else {
      reject(new Error('Validador no encontrado: ' + contexto));
    }
  });
}

async function validarConContexto(contexto, datos) {
  const { default: validador } = await cargarValidador(contexto);
  return validador.validar(datos);
}

const loginOK = await validarConContexto('login', { usuario: 'ana', password: '123456' });
const loginFail = await validarConContexto('login', { usuario: '', password: '123' });
const pagoOK = await validarConContexto('pago', { tarjeta: '1234567890123456' });

console.log(loginOK, loginFail, pagoOK);
